<?php
require 'common.php';require_admin();$id=(string)($_GET['id']??'');$rows=products();$idx=null;foreach($rows as$i=>$row)if(($row['id']??'')===$id){$idx=$i;break;}if($idx===null){http_response_code(404);exit('Product not found');}$p=$rows[$idx];$notice='';
