admin_head('تحرير المنتج');?><?php if($notice):?><div class="ok-box"><?=e($notice)?></div><?php endif;?><form class="panel settings-form" method="post"><div class="panel-head"><div><span>PRODUCT EDITOR</span><h2><?=e((string)($p['name']??''))?></h2></div><span class="quality-chip <?=product_quality($p)>=80?'good':'warn'?>">جودة <?=product_quality($p)?>%</span></div><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-two"><label>اسم المنتج<input name="name" value="<?=e((string)($p['name']??''))?>"></label><label>الموديل<input name="model" value="<?=e((string)($p['model']??''))?>"></label></div><div class="form-two"><label>العلامة<input name="brand" value="<?=e((string)($p['brand']??''))?>"></label><label>القسم<input name="category" value="<?=e((string)($p['category']??''))?>"></label></div><div class="form-two"><label>السعر<input type="number" step="0.01" name="price" value="<?=e((string)($p['price']??0))?>"></label><label>عبارة السعر<input name="price_label" value="<?=e((string)($p['price_label']??''))?>"></label></div><div class="form-two"><label>التوفر<input name="availability" value="<?=e((string)($p['availability']??''))?>"></label><label>الحالة<select name="status"><option value="draft" <?=($p['status']??'')==='draft'?'selected':''?>>مسودة</option><option value="published" <?=($p['status']??'')==='published'?'selected':''?>>منشور</option></select></label></div><label>الوصف المختصر<input name="short_description" value="<?=e((string)($p['short_description']??''))?>"></label><label>الوصف<textarea name="description" rows="5"><?=e((string)($p['description']??''))?></textarea></label><div class="form-two"><label>رابط المصدر<input name="source_url" value="<?=e((string)($p['source_url']??''))?>"></label><label>اسم المصدر<input name="source_name" value="<?=e((string)($p['source_name']??''))?>"></label></div><div class="form-two"><label>الصورة / المسار<input name="image" value="<?=e((string)($p['image']??''))?>"></label><label>درجة الثقة<input type="number" min="0" max="100" name="confidence" value="<?=e((string)($p['confidence']??0))?>"></label></div><div class="panel-head"><div><span>TECHNICAL DATA</span><h2>المواصفات</h2></div></div><div id="specRows"><?php foreach(($p['specs']??[]) as$k=>$v):?><div class="form-two spec-row"><label>الخاصية<input name="spec_key[]" value="<?=e((string)$k)?>"></label><label>القيمة<input name="spec_val[]" value="<?=e((string)$v)?>"></label></div><?php endforeach;?><div class="form-two spec-row"><label>خاصية جديدة<input name="spec_key[]"></label><label>القيمة<input name="spec_val[]"></label></div></div><button class="admin-btn" type="submit">حفظ التغييرات</button> <a class="admin-btn" href="products.php">رجوع</a></form><?php admin_foot();?>